import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"5、【需】 乾下坎上","description":"横渠易说 - 5、【需】 乾下坎上","frontmatter":{"title":"5、【需】 乾下坎上","description":"横渠易说 - 5、【需】 乾下坎上"},"headers":[],"relativePath":"zh/classics/hengqu/007.md","filePath":"zh/classics/hengqu/007.md"}'),t={name:"zh/classics/hengqu/007.md"};function l(n,a,s,c,d,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_5、【需】-乾下坎上" tabindex="-1">5、【需】 乾下坎上 <a class="header-anchor" href="#_5、【需】-乾下坎上" aria-label="Permalink to “5、【需】 乾下坎上”">​</a></h1><p>刚健而不陷而能俟时，故有孚于光亨也。讼、需、坎皆言“有学”，必然之理也。又如未济“饮酒濡首”亦言“有孚”，袭同此。</p><p>彖曰：需，须也，险在前也，刚健而不陷，其义不困穷矣。“需有孚光亨贞吉”，位乎天位，以正中也。</p><p>“利涉大川”，往有功也。</p><h3 id="象曰-云上放天-需-君子以饮食宴乐。" tabindex="-1">象曰：云上放天，需，君子以饮食宴乐。 <a class="header-anchor" href="#象曰-云上放天-需-君子以饮食宴乐。" aria-label="Permalink to “象曰：云上放天，需，君子以饮食宴乐。”">​</a></h3><p>“云上于天，需，君子以饮食宴乐”，九五，需于酒食贞吉”，未济亦“有孚于饮酒”，以阴在前，无所施为，惟于饮食而已。</p><h3 id="初九-需于郊-利用恒-无咎。-象曰-需于郊-不犯难行也。-利用恒无咎-未失常也。" tabindex="-1">初九，需于郊，利用恒，无咎。 象曰：“需于郊”，不犯难行也。“利用恒无咎”，未失常也。 <a class="header-anchor" href="#初九-需于郊-利用恒-无咎。-象曰-需于郊-不犯难行也。-利用恒无咎-未失常也。" aria-label="Permalink to “初九，需于郊，利用恒，无咎。 象曰：“需于郊”，不犯难行也。“利用恒无咎”，未失常也。”">​</a></h3><h3 id="九二-需于沙-小有言-终吉。-象曰-需于沙-衍在中也。虽小有言-以吉终也。" tabindex="-1">九二，需于沙，小有言，终吉。 象曰：“需于沙”，衍在中也。虽小有言，以吉终也。 <a class="header-anchor" href="#九二-需于沙-小有言-终吉。-象曰-需于沙-衍在中也。虽小有言-以吉终也。" aria-label="Permalink to “九二，需于沙，小有言，终吉。 象曰：“需于沙”，衍在中也。虽小有言，以吉终也。”">​</a></h3><h3 id="九三-需于泥-致寇至。-象曰-需于泥-灾在外也。自我致寇-敬慎不败也。" tabindex="-1">九三，需于泥，致寇至。 象曰：“需于泥”，灾在外也。自我致寇，敬慎不败也。 <a class="header-anchor" href="#九三-需于泥-致寇至。-象曰-需于泥-灾在外也。自我致寇-敬慎不败也。" aria-label="Permalink to “九三，需于泥，致寇至。 象曰：“需于泥”，灾在外也。自我致寇，敬慎不败也。”">​</a></h3><h3 id="六四-需于血-出自穴。-象曰-需于血-顺以听也。" tabindex="-1">六四，需于血，出自穴。 象曰：“需于血”，顺以听也。 <a class="header-anchor" href="#六四-需于血-出自穴。-象曰-需于血-顺以听也。" aria-label="Permalink to “六四，需于血，出自穴。 象曰：“需于血”，顺以听也。”">​</a></h3><p>以柔居阴，不能御弦，来则听顺而辟其路。</p><h3 id="九五-需于酒食-贞吉。-象曰-酒食贞吉-以中正也。" tabindex="-1">九五，需于酒食，贞吉。 象曰：酒食贞吉，以中正也。 <a class="header-anchor" href="#九五-需于酒食-贞吉。-象曰-酒食贞吉-以中正也。" aria-label="Permalink to “九五，需于酒食，贞吉。 象曰：酒食贞吉，以中正也。”">​</a></h3><h3 id="上六-入于穴-有不速之客三人来-敬之终吉。-象曰-不速之客来-敬之终吉。-虽不当位-未大失也。" tabindex="-1">上六，入于穴，有不速之客三人来，敬之终吉。 象曰：“不速之客来，敬之终吉。”虽不当位，未大失也。 <a class="header-anchor" href="#上六-入于穴-有不速之客三人来-敬之终吉。-象曰-不速之客来-敬之终吉。-虽不当位-未大失也。" aria-label="Permalink to “上六，入于穴，有不速之客三人来，敬之终吉。 象曰：“不速之客来，敬之终吉。”虽不当位，未大失也。”">​</a></h3><p>上无所出，故降人自穴，恭以纳之，虽处极上，不至于失。</p>',14)])])}const m=e(t,[["render",l]]);export{_ as __pageData,m as default};
